head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _3 : @param columnInfo 의 MultiLine caveat 전용 샘플.
//     한 데이터 레코드를 2개의 Line(TR)으로 표시(MultiLine).
//       Line1 : empNo(text, idx0) | name(text, idx1) | grade(select, nodeset itemset, idx2)
//       Line2 : memo(text, idx3) | region(select, nodeset itemset, idx4)
//     · Row 가 MultiLine(레코드당 2 Line)이어도 컬럼 인덱스는 Line 을 넘어 이어지는 고유값(0,1,2,3,4)을 가짐.
//       → Line1 의 select(grade, idx2) 와 Line2 의 select(region, idx4)는 서로 다른 고유 인덱스로
//         각각의 바인딩 객체({nodeset,value,label})를 반환한다. text 컬럼(0/1/3)은 undefined.
scwin.tData = {
    "description" : "[gridView > M > getColumnNodeSet]<br/>Body Column 정보를 사용하여 특정 Column 의 아이템으로 바인딩된 DataList 정보를 객체로 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - MultiLine(레코드당 2 Line) 그리드 : header / gBody 각각 <w2:row> 2개
//      Line1 : empNo(text) / name(text) / grade(select, dlt_grade nodeset itemset)
//      Line2 : memo(text)  / region(select, dlt_grade nodeset itemset)
//  - Line 을 넘어 컬럼 인덱스가 이어짐 : empNo=0, name=1, grade=2, memo=3, region=4
//      → Line1 select(grade,2) 와 Line2 select(region,4)는 서로 다른 고유 인덱스로 각각 채워진 객체 반환
//      → text 컬럼(empNo=0, name=1, memo=3)은 undefined
//  - dlt_grade : value ref=gCode, label ref=gLabel (select nodeset itemset 바인딩)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] MultiLine(레코드당 2 Line) 그리드. Line1=empNo(text,idx0)/name(text,idx1)/grade(select,dlt_grade nodeset itemset,idx2), Line2=memo(text,idx3)/region(select,dlt_grade nodeset itemset,idx4). Row 가 MultiLine 이어도 컬럼 인덱스는 Line 을 넘어 이어지는 고유값(0,1,2,3,4)을 가집니다. dlt_grade 는 value ref=gCode, label ref=gLabel.\n[절차] columnInfo(인덱스) 선택 후 (getColumnNodeSet 실행) 클릭. 99 는 유효하지 않은 인덱스.\n[확인] Line1 select(grade,idx2)와 Line2 select(region,idx4)가 서로 다른 고유 인덱스로 각각 채워진 객체(nodeset=data:dlt_grade, value=gCode, label=gLabel)를 반환 / text 컬럼(0/1/3)·유효하지않은인덱스(99)=undefined 가 반환영역에 출력됨."', '', 'label1');

    // 옵션용 DataList (코드/라벨) - value ref=gCode, label ref=gLabel
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="gCode" name="gCode" dataType="text"></w2:column>';
    strGrade += '<w2:column id="gLabel" name="gLabel" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "gCode": "A", "gLabel": "최우수" },
        { "gCode": "B", "gLabel": "우수" },
        { "gCode": "C", "gLabel": "보통" }
    ], false);

    // GridView 와 바인딩할 DataList 동적 생성 (각 Column 별 데이터)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="empNo" name="empNo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="grade" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "empNo": "1001", "name": "김철수", "grade": "A", "memo": "1차 검토 완료", "region": "A" },
        { "empNo": "1002", "name": "이영희", "grade": "B", "memo": "재검토 요청",   "region": "B" },
        { "empNo": "1003", "name": "박민수", "grade": "C", "memo": "신규 배정",     "region": "C" },
        { "empNo": "1004", "name": "정수진", "grade": "A", "memo": "승인 대기",     "region": "B" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // itemset(nodeset) 공통 조각 (select 용) : label ref=gLabel, value ref=gCode
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="gLabel"></w2:label><w2:value ref="gCode"></w2:value></w2:itemset></w2:choices>';

    // target 생성 : MultiLine(레코드당 2 Line) - header / gBody 각각 <w2:row> 2개
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' defaultCellHeight="30" id="" style="width:100%;height:320px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnNodeSet (MultiLine) 테스트 그리드"></w2:caption>';
    // Header : Line1(empNo/name/grade) / Line2(memo/region)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="90" inputType="text" id="h0" value="empNo(text)"></w2:column>';
    strTarget += '<w2:column width="120" inputType="text" id="h1" value="name(text)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h2" value="grade(select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="210" colspan="2" inputType="text" id="h3" value="memo(text)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="h4" value="region(select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1(empNo/name/grade) / Line2(memo/region) → 레코드당 2 TR Line
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // idx0 empNo (text) -> undefined
    strTarget += '<w2:column width="90" inputType="text" id="empNo" dataList="empNo"></w2:column>';
    // idx1 name (text) -> undefined
    strTarget += '<w2:column width="120" inputType="text" id="name" dataList="name"></w2:column>';
    // idx2 grade (select, dlt_grade nodeset itemset) -> 채워진 객체 (Line1)
    strTarget += '<w2:column width="150" inputType="select" id="grade" dataList="grade">' + itemset + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // idx3 memo (text) -> undefined
    strTarget += '<w2:column width="210" colspan="2" inputType="text" id="memo" dataList="memo"></w2:column>';
    // idx4 region (select, dlt_grade nodeset itemset) -> 채워진 객체 (Line2)
    strTarget += '<w2:column width="150" inputType="select" id="region" dataList="region">' + itemset + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getColumnNodeSet 조회 (메인 검증 - MultiLine 컬럼 고유 인덱스)
//  - Line1 select(grade, idx2) / Line2 select(region, idx4) -> 각각 서로 다른 고유 인덱스로 채워진 객체
//  - text 컬럼(idx0/1/3) / 유효하지 않은 인덱스(99) -> undefined
//  - 반환 객체 속성(nodeset/value/label) 개별 출력
scwin.btn_getColumnNodeSet_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    let colID = target1.getColumnID(columnInfo);
    let info = target1.getColumnNodeSet(columnInfo);

    let result;
    if (typeof info === 'undefined') {
        result = "undefined";
    } else if (info === null) {
        result = "null";
    } else {
        result = "nodeset='" + info.nodeset + "' / value='" + info.value + "' / label='" + info.label + "'";
    }

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnNodeSet(" + columnInfo + ") [getColumnID:" + colID + "] -> " + result);
}
